import{_ as t,o as r,c as n,ag as a}from"./chunks/framework.BRELbxIe.js";const p=JSON.parse(`{"title":"Dictionnaire des métaphores","description":"","frontmatter":{},"headers":[],"relativePath":"handout-06-dictionnaire.md","filePath":"handout-06-dictionnaire.md","handout":{"fichier":"handout-06-dictionnaire.md","markdown":"# Handout — Dictionnaire des métaphores\\n\\n**L'IA sous le capot — version métiers · Zenika · glossaire**\\n\\nToute la session raconte l'IA avec une seule image : la route et une entreprise de livraison. Ce dictionnaire réunit chaque notion, son image, le mot technique à reconnaître en réunion, ce qu'il faut en retenir et des outils réels qui la mettent en œuvre, dans l'ordre des parties.\\n\\n## Le dictionnaire\\n\\n| Partie | Notion                         | Métaphore                                                                                                   | Mot technique                                                       | Ce qu'il faut retenir                                                                          | En vrai, par exemple                                                |\\n| ------ | ------------------------------ | ----------------------------------------------------------------------------------------------------------- | ------------------------------------------------------------------- | ---------------------------------------------------------------------------------------------- | ------------------------------------------------------------------- |\\n| 1      | Grand modèle                   | le **moteur**                                                                                               | LLM                                                                 | puissant, mais il ne livre rien tout seul                                                      | GPT-5, Claude, Gemini, Mistral Large                                |\\n| 1      | Petit modèle                   | la **citadine** face au **poids lourd**                                                                     | SLM                                                                 | moins cher, peut rester « au garage » : vos données ne sortent pas                             | Phi-4, Gemma 3, Mistral Small (via Ollama)                          |\\n| 1      | Assistant                      | le **véhicule à qui vous passez commande** ; en simple conversation, la **course pas à pas**                | assistant, chatbot                                                  | vous êtes le commanditaire : vous décidez de chaque commande                                   | ChatGPT, Le Chat, Copilot Chat                                      |\\n| 1      | Automatisation à trajet fixe   | la **ligne de bus**                                                                                         | workflow                                                            | prévisible, peu cher, facile à vérifier                                                        | n8n, Make, Power Automate                                           |\\n| 1      | Assistant qui choisit sa route | le **taxi**                                                                                                 | agent                                                               | souple, mais coût et trajet imprévisibles                                                      | ChatGPT agent, Copilot agent                                        |\\n| 1      | Le logiciel autour du modèle   | le **véhicule** et son chauffeur                                                                            | agent, harness                                                      | le moteur propose, le véhicule agit                                                            | ChatGPT, Copilot, Claude Code                                       |\\n| 2      | Paramètres                     | les **chevaux** du moteur                                                                                   | paramètres                                                          | plus il y en a, plus le moteur est puissant, et gourmand ; le réglage compte autant            | Llama 3.1 : 8, 70 ou 405 milliards ; Mistral Small : 24 milliards   |\\n| 2      | Entraînement                   | l'**usine à moteurs** : fabrication, réglage, banc d'essai                                                  | pré-entraînement, fine-tuning, RLHF                                 | le moteur sort d'usine figé ; il n'apprend pas en vous parlant                                 | quelques motoristes : OpenAI, Anthropic, Google, Mistral, Meta      |\\n| 2      | Token                          | les **briques de Lego** du texte                                                                            | token                                                               | on lit, on est limité et on paie en briques, pas en mots                                       | une page ≈ 600 tokens ; prix au million de tokens                   |\\n| 2      | Prédiction                     | l'**autocomplétion** du téléphone, en géant                                                                 | génération du texte brique par brique                               | il cherche la suite plausible, pas la vérité                                                   | le token suivant, choisi parmi les plus probables                   |\\n| 2      | Embeddings                     | le **GPS des sens** : les mots proches habitent le même quartier                                            | embeddings                                                          | recherche par le sens, pas par le mot exact                                                    | recherche sémantique dans SharePoint, Glean, NotebookLM             |\\n| 2      | Attention                      | le **surligneur**                                                                                           | attention                                                           | chaque mot est compris grâce aux mots qui l'entourent                                          | le mécanisme des transformers (le « T » de GPT)                     |\\n| 2      | Context window                 | le **plan de travail**                                                                                      | context window                                                      | taille limitée, tout relu à chaque message, vidé à chaque conversation                         | de l'ordre de 200 000 à 1 million de tokens                         |\\n| 2      | Context window pleine          | le **plan de travail qui déborde**                                                                          | troncature, compaction, lost in the middle                          | il oublie le début, se perd au milieu, coûte plus : un sujet, une conversation                 | le résumé automatique de Claude et ChatGPT                          |\\n| 2      | Hallucination                  | le **GPS sûr de lui** qui invente une route                                                                 | hallucination                                                       | assuré ne veut pas dire exact : vérifier ce qui engage                                         | 2023 : six jurisprudences inventées par ChatGPT                     |\\n| 2      | Température                    | le **curseur de créativité**                                                                                | température                                                         | régulier ou inventif selon l'usage ; le hasard ne disparaît jamais                             | réglable dans les API (0 = le plus régulier)                        |\\n| 2      | Coût                           | le **taxi au compteur** ; le cache = l'**abonnement** du trajet quotidien                                   | tokens, cache                                                       | on paie ce qu'on envoie et ce qu'on reçoit                                                     | prix par million de tokens ; prompt caching jusqu'à −90 %           |\\n| 3      | Outils                         | la **boîte à outils**                                                                                       | tools                                                               | ce que le véhicule sait faire                                                                  | recherche web, lecture de fichiers, envoi de mails                  |\\n| 3      | MCP                            | le **quai de chargement standard** de chaque service                                                        | MCP, Model Context Protocol                                         | une seule norme pour relier agents et services ; ouvrir un quai, c'est donner un accès         | serveurs MCP pour Google Drive, Jira, Slack, Notion                 |\\n| 3      | RAG                            | l'**examen à livre ouvert**                                                                                 | RAG                                                                 | consulter vos documents avant de répondre, sans réentraîner                                    | Copilot sur SharePoint ; NotebookLM travaille à livre ouvert        |\\n| 3      | Mémoire                        | **post-it**, **carnet**, **archives**                                                                       | mémoire de l'assistant                                              | du texte recollé sur le plan de travail, jamais le moteur qui retient                          | la mémoire de ChatGPT, Claude, Copilot                              |\\n| 3      | Boucle de l'agent              | la **boucle du livreur** : regarder, agir, vérifier                                                         | boucle agentique                                                    | il tourne jusqu'à penser avoir fini : mission claire indispensable                             | un appel au modèle + un appel d'outil par tour                      |\\n| 4      | Harness                        | l'**équipement du véhicule** (coffre, frigo, hayon)                                                         | harness                                                             | même moteur, véhicules différents                                                              | ChatGPT, Copilot, Claude Code                                       |\\n| 4      | Orchestrateur                  | le **dispatch**                                                                                             | orchestrateur                                                       | répartit les tournées entre véhicules                                                          | LangGraph, CrewAI, n8n, sous-agents                                 |\\n| 4      | Patterns d'orchestration       | **chaîne de montage**, **aiguillage**, **équipes en parallèle**, **chef de chantier**, **contrôle qualité** | chaîne, routeur, parallélisation, orchestrateur-workers, évaluateur | on organise des agents comme une équipe                                                        | chaîne, routeur, parallélisation, orchestrateur-workers, évaluateur |\\n| 4      | SDD                            | le **dispatch par bons de commande**                                                                        | Spec-Driven Development                                             | rien ne part sans bon signé ; chaque bon devient une tournée confiée à un agent                | GitHub Spec Kit, Kiro                                               |\\n| 5      | Injection de prompt            | un **faux ordre de mission** glissé dans un colis                                                           | prompt injection                                                    | l'agent obéit à ce qu'il lit                                                                   | texte blanc caché dans un CV, mail piégé (OWASP LLM01)              |\\n| 5      | Trio létal                     | **les clés + un inconnu + une porte ouverte**                                                               | lethal trifecta                                                     | supprimer un des trois suffit                                                                  | un assistant qui lit et envoie vos mails                            |\\n| 5      | Guardrails                     | les **contrôles du boîtier**, à l'aller et au retour                                                        | guardrails                                                          | les contrôles réduisent le risque ; les autorisations du véhicule (sur les actions) le bornent | Azure AI Content Safety, AWS Bedrock Guardrails, Llama Guard        |\\n| 5      | Gateway                        | le **boîtier de la flotte**, entre la pédale et le moteur                                                   | gateway IA                                                          | il bride, il compte, il enregistre : le même pour tous les véhicules                           | LiteLLM, Kong AI Gateway, Azure API Management                      |\\n\\n## Les limites des images\\n\\nUne métaphore aide à comprendre, pas à tout prédire.\\n\\n- Un vrai moteur ne décide rien ; un modèle d'IA, lui, choisit la prochaine action d'un agent.\\n- Le modèle n'agit jamais lui-même : c'est le véhicule qui exécute, et c'est là qu'on place les règles.\\n- Un vrai boîtier de flotte ne change pas de moteur ; la gateway, elle, sait envoyer une demande vers un autre modèle.\\n- Un même produit peut jouer plusieurs rôles : on classe des rôles, pas des marques.\\n"}}`),i={name:"handout-06-dictionnaire.md"};function o(d,e,s,l,u,c){return r(),n("div",null,[...e[0]||(e[0]=[a("",8)])])}const g=t(i,[["render",o]]);export{p as __pageData,g as default};
